/**
 * Garage Card - Top-Down View
 * A custom Home Assistant Lovelace card for garage visualization
 * https://github.com/KadenThomp36/garage-card
 */

const GARAGE_EMBEDDED_ASSETS = {
  'garage-base.png': 'data:image/png;base64,',
  'garage-door-closed.png': 'data:image/png;base64,',
  'car-1.png': 'data:image/png;base64,',
  'car-2.png': 'data:image/png;base64,'
};

const CARD_VERSION = '1.5.0';
const LEGACY_ASSETS_PATH = '/local/garage-card/assets';
const HOLD_MS = 500;
const TIMER_INTERVAL_MS = 15000;
const UNAVAILABLE_STATES = ['unavailable', 'unknown'];
const COVER_SUPPORT_STOP = 8;

const GARAGE_LABELS = {
  name: 'Card name',
  door_entity: 'Garage door',
  door2_entity: 'Second garage door (optional)',
  door_confirmation: 'Ask for confirmation before moving a door',
  car1_presence_entity: 'Car 1 presence (optional)',
  car2_presence_entity: 'Car 2 presence (optional)',
  car3_presence_entity: 'Car 3 presence (optional)',
  light_entity: 'Garage light (optional)',
  keep_open_entity: 'Keep open toggle (optional)',
  assets_path: 'Custom assets path (optional)'
};

const GARAGE_HELPERS = {
  door2_entity: 'For garages with two separate doors. Door 1 covers the left bay (car 1), door 2 the right bay (car 2).',
  car1_presence_entity: 'Car 1 is drawn in the left bay.',
  car2_presence_entity: 'Car 2 is drawn in the right bay.',
  car3_presence_entity: 'Car 3 has no built-in image and needs custom assets.',
  keep_open_entity: 'An input_boolean you use in your own automations (e.g. the companion blueprints) to skip auto-close.',
  assets_path: 'Folder with your own garage-base.png, garage-door-closed.png and car-N.png, e.g. /local/garage-card/assets. Leave empty to use the built-in images.'
};

const presenceSelector = {
  entity: {
    filter: [
      { domain: 'binary_sensor' },
      { domain: 'input_boolean' },
      { domain: 'device_tracker' },
      { domain: 'person' }
    ]
  }
};

const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
})[c]);

class GarageCard extends HTMLElement {
  static getConfigForm() {
    return {
      schema: [
        { name: 'name', selector: { text: {} } },
        { name: 'door_entity', required: true, selector: { entity: { filter: { domain: 'cover' } } } },
        { name: 'door2_entity', selector: { entity: { filter: { domain: 'cover' } } } },
        { name: 'door_confirmation', selector: { boolean: {} } },
        {
          name: 'cars',
          type: 'expandable',
          flatten: true,
          title: 'Cars',
          icon: 'mdi:car',
          schema: [
            { name: 'car1_presence_entity', selector: presenceSelector },
            { name: 'car2_presence_entity', selector: presenceSelector },
            { name: 'car3_presence_entity', selector: presenceSelector }
          ]
        },
        { name: 'light_entity', selector: { entity: { filter: [{ domain: 'light' }, { domain: 'switch' }] } } },
        { name: 'keep_open_entity', selector: { entity: { filter: { domain: 'input_boolean' } } } },
        {
          name: 'advanced',
          type: 'expandable',
          flatten: true,
          title: 'Custom images',
          icon: 'mdi:image-edit-outline',
          schema: [
            { name: 'assets_path', selector: { text: {} } }
          ]
        }
      ],
      computeLabel: (schema) => GARAGE_LABELS[schema.name],
      computeHelper: (schema) => GARAGE_HELPERS[schema.name]
    };
  }

  static getStubConfig(hass) {
    const ids = Object.keys(hass?.states ?? {});
    const covers = ids.filter((id) => id.startsWith('cover.'));
    const door = covers.find((id) => hass.states[id].attributes?.device_class === 'garage') ?? covers[0] ?? '';
    return { name: 'Garage', door_entity: door };
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._config = null;
    this._hass = null;
    this._timer = null;
    this._lastStates = new Map();
  }

  connectedCallback() {
    this._startTimer();
    if (this._hass) this._update(true);
  }

  disconnectedCallback() {
    if (this._timer) {
      clearInterval(this._timer);
      this._timer = null;
    }
  }

  setConfig(config) {
    if (!config || typeof config !== 'object') {
      throw new Error('Invalid configuration');
    }
    if (!config.door_entity) {
      throw new Error('door_entity is required');
    }
    this._config = { name: 'Garage', ...config };
    this._render();
  }

  set hass(hass) {
    this._hass = hass;
    this._update();
  }

  get hass() {
    return this._hass;
  }

  getCardSize() {
    return 9;
  }

  getGridOptions() {
    return { columns: 12, min_columns: 6 };
  }

  // ---------- Config helpers ----------

  _getDoors() {
    const doors = [{ index: 1, entity: this._config.door_entity }];
    if (this._config.door2_entity) {
      doors.push({ index: 2, entity: this._config.door2_entity });
    }
    if (doors.length > 1) {
      doors[0].label = 'Left';
      doors[1].label = 'Right';
    }
    return doors;
  }

  _getCars() {
    const cars = [];
    for (let i = 1; i <= 3; i++) {
      const entity = this._config[`car${i}_presence_entity`];
      if (entity) cars.push({ index: i, entity, image: `car-${i}.png` });
    }
    return cars;
  }

  _trackedEntities() {
    return [
      ...this._getDoors().map((d) => d.entity),
      ...this._getCars().map((c) => c.entity),
      this._config.light_entity,
      this._config.keep_open_entity
    ].filter(Boolean);
  }

  _getAssetSrc(filename) {
    const path = this._config.assets_path?.replace(/\/+$/, '');
    if (path && path !== LEGACY_ASSETS_PATH) {
      return `${path}/${filename}`;
    }
    return GARAGE_EMBEDDED_ASSETS[filename] || '';
  }

  // ---------- State helpers ----------

  _stateObj(entityId) {
    return entityId ? this._hass?.states[entityId] : undefined;
  }

  _isOn(entityId) {
    return this._stateObj(entityId)?.state === 'on';
  }

  _isCarPresent(entityId) {
    const state = this._stateObj(entityId)?.state;
    return state === 'on' || state === 'home';
  }

  _formatState(stateObj) {
    if (!stateObj) {
      return this._hass?.localize?.('ui.card.common.entity_not_found') || 'Not found';
    }
    if (this._hass?.formatEntityState) {
      return this._hass.formatEntityState(stateObj);
    }
    return stateObj.state.charAt(0).toUpperCase() + stateObj.state.slice(1);
  }

  _locale() {
    return this._hass?.locale?.language || this._hass?.language || undefined;
  }

  _formatTime(date) {
    const opts = { hour: 'numeric', minute: '2-digit' };
    const timeFormat = this._hass?.locale?.time_format;
    if (timeFormat === '12') opts.hour12 = true;
    if (timeFormat === '24') opts.hour12 = false;
    if (Date.now() - date.getTime() > 24 * 3600 * 1000) {
      opts.month = 'short';
      opts.day = 'numeric';
    }
    try {
      return new Intl.DateTimeFormat(this._locale(), opts).format(date);
    } catch (e) {
      return date.toLocaleTimeString();
    }
  }

  _formatDuration(date) {
    const totalMins = Math.max(0, Math.floor((Date.now() - date.getTime()) / 60000));
    const days = Math.floor(totalMins / 1440);
    const hours = Math.floor((totalMins % 1440) / 60);
    const mins = totalMins % 60;
    if (days > 0) return `${days}d ${hours}h`;
    if (hours > 0) return `${hours}h ${mins}m`;
    return `${mins}m`;
  }

  _carTimeText(entityId) {
    const lastChanged = this._stateObj(entityId)?.last_changed;
    if (!lastChanged) return '';
    const date = new Date(lastChanged);
    return `${this._formatTime(date)} \u2022 ${this._formatDuration(date)}`;
  }

  // ---------- Actions (handled natively by HA via hass-action) ----------

  _fireAction(entity, action, tapAction) {
    const ev = new Event('hass-action', { bubbles: true, composed: true });
    ev.detail = {
      config: {
        entity,
        tap_action: tapAction,
        hold_action: { action: 'more-info' }
      },
      action
    };
    this.dispatchEvent(ev);
  }

  _doorTapAction(entity) {
    const stateObj = this._stateObj(entity);
    if (!stateObj || UNAVAILABLE_STATES.includes(stateObj.state)) {
      return { action: 'more-info' };
    }
    const action = {
      action: 'perform-action',
      perform_action: 'cover.toggle',
      target: { entity_id: entity }
    };
    if (this._config.door_confirmation) {
      const name = stateObj.attributes?.friendly_name || 'the garage door';
      // Mirrors core's cover.toggle: stop while moving (if supported), else reverse.
      const canStop = ((stateObj.attributes?.supported_features ?? 0) & COVER_SUPPORT_STOP) !== 0;
      const moving = stateObj.state === 'opening' || stateObj.state === 'closing';
      const verb = moving && canStop ? 'Stop'
        : ['closed', 'closing'].includes(stateObj.state) ? 'Open' : 'Close';
      action.confirmation = { text: `${verb} ${name}?` };
    }
    return action;
  }

  /**
   * Wires tap + hold (more-info) on an element. getTapAction is evaluated at
   * tap time so it always reflects the current entity state.
   */
  _bindAction(el, entity, getTapAction) {
    if (!el) return;
    let timer = null;
    let held = false;
    const clear = () => {
      if (timer) clearTimeout(timer);
      timer = null;
    };
    el.addEventListener('pointerdown', (e) => {
      if (e.button !== 0) return;
      held = false;
      clear();
      timer = setTimeout(() => {
        held = true;
        this._fireAction(entity, 'hold', getTapAction());
      }, HOLD_MS);
    });
    ['pointerup', 'pointerleave', 'pointercancel'].forEach((type) => el.addEventListener(type, clear));
    el.addEventListener('contextmenu', (e) => e.preventDefault());
    el.addEventListener('click', (e) => {
      e.stopPropagation();
      if (held) {
        held = false;
        return;
      }
      this._fireAction(entity, 'tap', getTapAction());
    });
  }

  // ---------- Rendering ----------

  _render() {
    if (!this._config) return;

    const doors = this._getDoors();
    const cars = this._getCars();
    const hasLight = Boolean(this._config.light_entity);
    const twoDoors = doors.length > 1;

    this.shadowRoot.innerHTML = `
      <style>${GarageCard._styles}</style>
      <ha-card>
        <div class="garage-card">
          ${this._config.name ? `
            <div class="header">
              <span class="header-title">${escapeHtml(this._config.name)}</span>
            </div>
          ` : ''}

          <div class="garage-scene ${hasLight ? 'has-light' : ''}" id="garage-scene">
            ${doors.map((door) => `
              <div class="door-touch-target ${twoDoors ? `half door-${door.index}` : ''}"
                   id="door${door.index}-target" role="button" tabindex="0"
                   aria-label="${escapeHtml(door.label ? `${door.label} garage door` : 'Garage door')}"></div>
            `).join('')}
            <div class="layer garage-base">
              <img src="${this._getAssetSrc('garage-base.png')}" alt="">
            </div>
            ${cars.map((car) => `
              <div class="layer car away" id="car-${car.index}">
                <img src="${this._getAssetSrc(car.image)}" alt="">
              </div>
            `).join('')}
            ${doors.map((door) => `
              <div class="layer garage-door ${twoDoors ? `split door-${door.index}` : ''}" id="door${door.index}-layer">
                <img src="${this._getAssetSrc('garage-door-closed.png')}" alt="">
              </div>
            `).join('')}
            ${hasLight ? `
              <button class="light-btn" id="light-toggle" aria-label="Garage light">
                <ha-icon icon="mdi:lightbulb-outline" id="light-icon"></ha-icon>
              </button>
            ` : ''}
          </div>

          <div class="status-bar">
            <div class="controls-row">
              ${doors.map((door) => `
                <button class="pill door-status" id="door${door.index}-toggle">
                  <span class="indicator" id="door${door.index}-indicator"></span>
                  ${door.label ? `<span class="door-label">${door.label}</span>` : ''}
                  <span class="text" id="door${door.index}-text"></span>
                  <ha-icon icon="mdi:garage" id="door${door.index}-icon"></ha-icon>
                </button>
              `).join('')}
              ${this._config.keep_open_entity ? `
                <button class="pill keep-open-toggle" id="keep-open-toggle" role="switch" aria-checked="false">
                  <ha-icon icon="mdi:lock-open-variant-outline"></ha-icon>
                  <span>Keep Open</span>
                  <span class="toggle-indicator"></span>
                </button>
              ` : ''}
            </div>
            ${cars.length > 0 ? `
              <div class="car-status">
                ${cars.map((car) => `
                  <button class="car-badge" id="car${car.index}-badge">
                    <span class="badge-row">
                      <span class="dot" id="car${car.index}-dot"></span>
                      <span class="status" id="car${car.index}-status"></span>
                    </span>
                    <span class="time-info" id="car${car.index}-time"></span>
                  </button>
                `).join('')}
              </div>
            ` : ''}
          </div>
        </div>
      </ha-card>
    `;

    const $ = (id) => this.shadowRoot.getElementById(id);
    for (const door of doors) {
      const tap = () => this._doorTapAction(door.entity);
      this._bindAction($(`door${door.index}-target`), door.entity, tap);
      this._bindAction($(`door${door.index}-toggle`), door.entity, tap);
      $(`door${door.index}-target`).addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          this._fireAction(door.entity, 'tap', tap());
        }
      });
    }
    if (hasLight) {
      this._bindAction($('light-toggle'), this._config.light_entity, () => ({ action: 'toggle' }));
    }
    if (this._config.keep_open_entity) {
      this._bindAction($('keep-open-toggle'), this._config.keep_open_entity, () => ({ action: 'toggle' }));
    }
    for (const car of cars) {
      this._bindAction($(`car${car.index}-badge`), car.entity, () => ({ action: 'more-info' }));
    }

    this._lastStates.clear();
    if (this._hass) this._update(true);
  }

  _update(force = false) {
    if (!this._config || !this._hass || !this.shadowRoot.querySelector('ha-card')) return;

    // Skip DOM work when none of our entities changed.
    let changed = force;
    for (const id of this._trackedEntities()) {
      const stateObj = this._hass.states[id];
      if (!this._lastStates.has(id) || this._lastStates.get(id) !== stateObj) {
        this._lastStates.set(id, stateObj);
        changed = true;
      }
    }
    if (!changed) return;

    const $ = (id) => this.shadowRoot.getElementById(id);

    for (const door of this._getDoors()) {
      const stateObj = this._stateObj(door.entity);
      const state = stateObj?.state ?? 'unavailable';
      const unavailable = UNAVAILABLE_STATES.includes(state);
      const isOpen = state === 'open' || state === 'opening';
      const isMoving = state === 'opening' || state === 'closing';

      const layer = $(`door${door.index}-layer`);
      layer?.classList.toggle('open', isOpen);
      layer?.classList.toggle('moving', isMoving);

      const indicator = $(`door${door.index}-indicator`);
      indicator?.classList.toggle('open', isOpen && !isMoving);
      indicator?.classList.toggle('moving', isMoving);
      indicator?.classList.toggle('unavailable', unavailable);

      const text = $(`door${door.index}-text`);
      if (text) text.textContent = this._formatState(stateObj);

      $(`door${door.index}-icon`)?.setAttribute('icon', isOpen ? 'mdi:garage-open' : 'mdi:garage');
      $(`door${door.index}-toggle`)?.classList.toggle('unavailable', unavailable);
    }

    for (const car of this._getCars()) {
      const present = this._isCarPresent(car.entity);
      const known = Boolean(this._stateObj(car.entity)) &&
        !UNAVAILABLE_STATES.includes(this._stateObj(car.entity).state);
      $(`car-${car.index}`)?.classList.toggle('away', !present);
      $(`car${car.index}-dot`)?.classList.toggle('home', present);
      const status = $(`car${car.index}-status`);
      if (status) {
        status.textContent = !known ? this._formatState(this._stateObj(car.entity)) : present ? 'Home' : 'Away';
        status.classList.toggle('home', present);
      }
    }
    this._updateTimers();

    if (this._config.light_entity) {
      const lightOn = this._isOn(this._config.light_entity);
      $('garage-scene')?.classList.toggle('lit', lightOn);
      $('light-toggle')?.classList.toggle('on', lightOn);
      $('light-icon')?.setAttribute('icon', lightOn ? 'mdi:lightbulb' : 'mdi:lightbulb-outline');
    }

    const keepOpen = $('keep-open-toggle');
    if (keepOpen) {
      const enabled = this._isOn(this._config.keep_open_entity);
      keepOpen.classList.toggle('enabled', enabled);
      keepOpen.setAttribute('aria-checked', String(enabled));
    }
  }

  _startTimer() {
    if (this._timer) return;
    this._timer = setInterval(() => this._updateTimers(), TIMER_INTERVAL_MS);
  }

  _updateTimers() {
    if (!this._config || !this._hass) return;
    for (const car of this._getCars()) {
      const el = this.shadowRoot.getElementById(`car${car.index}-time`);
      if (el) el.textContent = this._carTimeText(car.entity);
    }
  }

  static get _styles() {
    return `
      :host {
        --status-home: var(--green-color, #32D74B);
        --status-away: var(--secondary-text-color, #888);
        --door-open: var(--green-color, #32D74B);
        --door-closed: var(--red-color, #FF453A);
        --door-moving: var(--warning-color, #FF9F0A);
        --door-unavailable: var(--state-unavailable-color, #bdbdbd);
      }

      :host {
        display: block;
      }

      ha-card {
        height: 100%;
      }

      .garage-card {
        padding: 16px;
        color: var(--primary-text-color);
      }

      .header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-bottom: 12px;
      }

      .header-title {
        font-size: 1.3em;
        font-weight: 600;
      }

      .garage-scene {
        position: relative;
        width: 100%;
        aspect-ratio: 1 / 1;
        margin: 0 auto;
      }

      .garage-scene.has-light {
        filter: brightness(0.6);
        transition: filter 0.5s ease;
      }

      .garage-scene.has-light.lit {
        filter: brightness(1);
      }

      .door-touch-target {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 33.33%;
        z-index: 5;
        cursor: pointer;
        -webkit-tap-highlight-color: transparent;
        outline: none;
        border-radius: 12px;
        user-select: none;
        -webkit-user-select: none;
        -webkit-touch-callout: none;
      }

      .door-touch-target:focus-visible {
        box-shadow: inset 0 0 0 2px var(--primary-color);
      }

      .door-touch-target.half {
        width: 50%;
      }

      .door-touch-target.half.door-2 {
        left: 50%;
      }

      .layer {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        pointer-events: none;
      }

      .layer img {
        width: 100%;
        height: 100%;
        object-fit: contain;
      }

      .garage-base {
        z-index: 1;
      }

      .car {
        z-index: 2;
        opacity: 1;
        filter: grayscale(0%);
        transition: opacity 0.4s ease, filter 0.4s ease;
      }

      .car.away {
        opacity: 0.15;
        filter: grayscale(100%);
      }

      .garage-door {
        z-index: 3;
        opacity: 1;
        transition: opacity 0.6s ease;
      }

      /* Two-door mode: each door shows its half of the door overlay */
      .garage-door.split.door-1 {
        clip-path: inset(0 50% 0 0);
      }

      .garage-door.split.door-2 {
        clip-path: inset(0 0 0 50%);
      }

      .garage-door.open {
        opacity: 0;
      }

      .garage-door.moving {
        animation: doorPulse 0.8s ease-in-out infinite;
      }

      @keyframes doorPulse {
        0%, 100% { opacity: 0.8; }
        50% { opacity: 0.3; }
      }

      button {
        font: inherit;
        color: inherit;
        border: none;
        margin: 0;
      }

      button:focus-visible {
        outline: 2px solid var(--primary-color);
        outline-offset: 2px;
      }

      .light-btn {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        z-index: 10;
        background: rgba(0, 0, 0, 0.4);
        border: 2px solid rgba(255, 255, 255, 0.3);
        border-radius: 50%;
        width: 48px;
        height: 48px;
        padding: 0;
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        transition: all 0.3s ease;
        backdrop-filter: blur(4px);
        -webkit-backdrop-filter: blur(4px);
        -webkit-tap-highlight-color: transparent;
      }

      .light-btn:hover {
        background: rgba(0, 0, 0, 0.5);
        transform: translate(-50%, -50%) scale(1.1);
      }

      .light-btn.on {
        background: var(--warning-color, #FF9F0A);
        border-color: var(--warning-color, #FF9F0A);
        box-shadow: 0 0 20px rgba(255, 159, 10, 0.5);
      }

      .light-btn ha-icon {
        --mdc-icon-size: 24px;
        color: rgba(255, 255, 255, 0.8);
        transition: color 0.3s ease;
      }

      .light-btn.on ha-icon {
        color: #000;
      }

      .status-bar {
        display: flex;
        flex-direction: column;
        gap: 12px;
        margin-top: 12px;
        padding-top: 12px;
        border-top: 1px solid var(--divider-color, rgba(255, 255, 255, 0.1));
        align-items: center;
      }

      .controls-row {
        display: flex;
        gap: 8px;
        justify-content: center;
        flex-wrap: wrap;
        align-items: stretch;
      }

      .pill,
      .car-badge,
      .light-btn {
        -webkit-touch-callout: none;
        -webkit-user-select: none;
        user-select: none;
      }

      .pill {
        display: flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 20px;
        background: var(--secondary-background-color);
        font-size: 0.85em;
        cursor: pointer;
        transition: background 0.2s ease;
        user-select: none;
        -webkit-tap-highlight-color: transparent;
        height: 36px;
        box-sizing: border-box;
      }

      .pill:hover {
        background: var(--primary-background-color);
      }

      .pill:active {
        transform: scale(0.97);
      }

      .door-status .indicator {
        width: 10px;
        height: 10px;
        border-radius: 50%;
        background: var(--door-closed);
        transition: background 0.3s ease;
      }

      .door-status .indicator.open {
        background: var(--door-open);
      }

      .door-status .indicator.moving {
        background: var(--door-moving);
        animation: pulse 1s ease-in-out infinite;
      }

      .door-status .indicator.unavailable {
        background: var(--door-unavailable);
      }

      .door-status.unavailable .text {
        color: var(--secondary-text-color);
      }

      @keyframes pulse {
        0%, 100% { opacity: 1; transform: scale(1); }
        50% { opacity: 0.6; transform: scale(0.85); }
      }

      .door-status .door-label {
        color: var(--secondary-text-color);
      }

      .door-status .text {
        font-weight: 500;
      }

      .keep-open-toggle {
        gap: 6px;
      }

      .keep-open-toggle.enabled {
        background: color-mix(in srgb, var(--status-home) 20%, transparent);
      }

      .keep-open-toggle .toggle-indicator {
        width: 32px;
        height: 18px;
        border-radius: 9px;
        background: var(--disabled-color, #555);
        position: relative;
        transition: background 0.2s ease;
      }

      .keep-open-toggle.enabled .toggle-indicator {
        background: var(--status-home);
      }

      .keep-open-toggle .toggle-indicator::after {
        content: '';
        position: absolute;
        width: 14px;
        height: 14px;
        border-radius: 50%;
        background: white;
        top: 2px;
        left: 2px;
        transition: transform 0.2s ease;
      }

      .keep-open-toggle.enabled .toggle-indicator::after {
        transform: translateX(14px);
      }

      .keep-open-toggle ha-icon {
        --mdc-icon-size: 16px;
      }

      .door-status ha-icon {
        --mdc-icon-size: 20px;
      }

      .car-status {
        display: flex;
        gap: 24px;
        justify-content: center;
        flex-wrap: wrap;
      }

      .car-badge {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 2px;
        font-size: 0.9em;
        background: none;
        padding: 4px 8px;
        border-radius: 8px;
        cursor: pointer;
        -webkit-tap-highlight-color: transparent;
      }

      .car-badge .badge-row {
        display: flex;
        align-items: center;
        gap: 6px;
      }

      .car-badge .dot {
        width: 8px;
        height: 8px;
        border-radius: 50%;
        background: var(--status-away);
        transition: background 0.3s ease;
      }

      .car-badge .dot.home {
        background: var(--status-home);
      }

      .car-badge .status {
        font-weight: 500;
        color: var(--status-away);
        transition: color 0.3s ease;
      }

      .car-badge .status.home {
        color: var(--status-home);
      }

      .car-badge .time-info {
        font-size: 0.75em;
        color: var(--secondary-text-color);
        opacity: 0.8;
        text-align: center;
      }
    `;
  }
}

customElements.define('garage-card', GarageCard);

window.customCards = window.customCards || [];
window.customCards.push({
  type: 'garage-card',
  name: 'Garage Card',
  description: 'Top-down garage view with door control, car presence and light control',
  preview: true,
  documentationURL: 'https://github.com/KadenThomp36/garage-card'
});

console.info(`%c GARAGE-CARD %c v${CARD_VERSION} `,
  'color: white; background: #4A90D9; font-weight: bold;',
  'color: #4A90D9; background: white; font-weight: bold;'
);
